1	use std::sync::Arc;
2	
3	use cudarc::driver::CudaSlice;
4	use cudarc::driver::CudaStream;
5	use cudarc::driver::DevicePtr;
6	use half::bf16;
7	
8	use crate::KvLayout;
9	
10	struct Inner {
11	    buffer: CudaSlice<bf16>,
12	    layout: KvLayout,
13	    num_blocks: usize,
14	}
15	
16	/// GPU KV cache buffer without an allocator.
17	///
18	/// Owns the device memory and layout geometry but delegates block
19	/// allocation to an external `BlockManager` (kvbm-logical).
20	#[derive(Clone)]
21	pub struct KvBuffer {
22	    inner: Arc<Inner>,
23	}
24	
25	impl KvBuffer {
26	    pub fn new(
27	        stream: &Arc<CudaStream>,
28	        num_layers: usize,
29	        num_kv_heads: usize,
30	        head_dim: usize,
31	        page_size: usize,
32	        num_blocks: usize,
33	    ) -> anyhow::Result<Self> {
34	        let layout = KvLayout::new(num_layers, num_kv_heads, head_dim, page_size);
35	        let total_elements = num_blocks * layout.page_stride;
36	        let buffer: CudaSlice<bf16> = stream
37	            .alloc_zeros(total_elements)
38	            .map_err(|e| anyhow::anyhow!("KvBuffer alloc failed: {e}"))?;
39	        Ok(Self {
40	            inner: Arc::new(Inner {
41	                buffer,
42	                layout,
43	                num_blocks,
44	            }),
45	        })
46	    }
47	
48	    pub fn layout(&self) -> &KvLayout {
49	        &self.inner.layout
50	    }
51	
52	    pub fn buffer(&self) -> &CudaSlice<bf16> {
53	        &self.inner.buffer
54	    }
55	
56	    /// Base device address of the fused KV buffer.
57	    ///
58	    /// Stable for the buffer's lifetime — cudarc allocations don't move — so
59	    /// the KV-offload connector registers this once with pegaflow and the
60	    /// page-first [`KvLayout`] strides reach every (layer, block, K/V) segment
61	    /// from it. The returned address outlives the transient stream-ordering
62	    /// guard precisely because the `Arc<Inner>` keeps the slice alive.
63	    pub fn device_ptr(&self, stream: &CudaStream) -> u64 {
64	        let (ptr, _guard) = self.inner.buffer.device_ptr(stream);
65	        ptr
66	    }
67	
68	    pub fn num_blocks(&self) -> usize {
69	        self.inner.num_blocks
70	    }
71	
72	    /// Stream-ordered device-to-device copy of one whole page (every layer's
73	    /// K/V for `page_size` tokens — one contiguous `page_stride` range in the
74	    /// page-first layout). Both pages must lie inside the buffer; scratch
75	    /// pages past the pool's block count are valid targets.
76	    pub fn copy_page(
77	        &self,
78	        stream: &CudaStream,
79	        src_page: usize,
80	        dst_page: usize,
81	    ) -> anyhow::Result<()> {
82	        anyhow::ensure!(
83	            src_page < self.inner.num_blocks && dst_page < self.inner.num_blocks,
84	            "KV page copy out of range: {src_page} -> {dst_page} of {}",
85	            self.inner.num_blocks
86	        );
87	        if src_page == dst_page {
88	            return Ok(());
89	        }
90	        let stride = self.inner.layout.page_stride;
91	        let elem = std::mem::size_of::<bf16>();
92	        let (base, _guard) = self.inner.buffer.device_ptr(stream);
93	        let src = base + (src_page * stride * elem) as u64;
94	        let dst = base + (dst_page * stride * elem) as u64;
95	        unsafe {
96	            cudarc::driver::result::memcpy_dtod_async(dst, src, stride * elem, stream.cu_stream())
97	        }
98	        .map_err(|e| anyhow::anyhow!("KV page copy failed: {e}"))
99	    }
100	}
